/* Layered SVG glass, with a guarded direction transition shared by all controls. */
function glassMix(hex,target,amount){let raw=hex.replace('#','');if(raw.length===3)raw=raw.split('').map(x=>x+x).join('');let n=parseInt(raw,16),t=parseInt(target.replace('#',''),16);return '#'+[16,8,0].map(shift=>Math.round(((n>>shift)&255)*(1-amount)+((t>>shift)&255)*amount).toString(16).padStart(2,'0')).join('')}
interactiveArc=function(a){let pct=a.fraction*100,key=arrivalRoute+'|'+arrivalDirection+'|'+arrivalBoard+'|'+a.riding+'|'+a.choice?.v.number,previous=arcPrevious.key===key?arcPrevious.value:pct;arcPrevious={key,value:pct};let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,dur=reduced?'0.001s':'.8s',path='M20 104C35 -10 285 -10 300 104',color=a.m.route.color,light=glassMix(color,'#ffffff',.57),dark=glassMix(color,'#10182a',.34),pale=glassMix(color,'#ffffff',.82);let animate="",point=MetroProgress.arcPoint(a.fraction);return `<button class="journey-dome progress-dome glass-dome" data-arc-key="${safe(key)}" onclick="arcProgressDetails()" aria-label="${a.riding?'Your ride':'Bus approaching'}: ${Math.round(pct)} percent complete. View journey progress"><svg viewBox="0 0 320 129" aria-hidden="true"><defs><linearGradient id="arc-glass-body" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${light}"/><stop offset=".32" stop-color="${color}"/><stop offset=".7" stop-color="${color}"/><stop offset="1" stop-color="${dark}"/></linearGradient><linearGradient id="arc-glass-track" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#fff"/><stop offset=".4" stop-color="${pale}"/><stop offset="1" stop-color="${glassMix(color,'#ffffff',.65)}"/></linearGradient><linearGradient id="arc-glass-highlight" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".9"/><stop offset=".42" stop-color="#fff" stop-opacity=".5"/><stop offset="1" stop-color="#fff" stop-opacity=".12"/></linearGradient><radialGradient id="arc-glass-bus" cx=".3" cy=".2" r=".9"><stop stop-color="${light}"/><stop offset=".45" stop-color="${color}"/><stop offset="1" stop-color="${dark}"/></radialGradient><filter id="arc-glass-shadow" x="-30%" y="-50%" width="160%" height="220%" color-interpolation-filters="sRGB"><feDropShadow dx="0" dy="3" stdDeviation="2.2" flood-color="${dark}" flood-opacity=".2"/></filter></defs><path d="${path}" class="glass-ground-shadow" transform="translate(0 5)"/><path d="${path}" class="glass-track-body"/><path d="${path}" class="glass-track-shine" transform="translate(0 -2.5)"/><path d="${path}" class="glass-fill-depth" pathLength="100" stroke-dasharray="${pct} 100">${animate}</path><path d="${path}" class="glass-fill-body" pathLength="100" stroke-dasharray="${pct} 100">${animate}</path><path d="${path}" class="glass-fill-shine" transform="translate(0 -2.6)" pathLength="100" stroke-dasharray="${pct} 100">${animate}</path><path d="${path}" class="glass-liquid-glint" pathLength="100" style="animation-delay:-${(performance.now()/1000)%4.8}s"/><ellipse cx="20" cy="111" rx="9" ry="2.5" fill="${dark}" opacity=".13"/><circle cx="20" cy="104" r="5" fill="url(#arc-glass-bus)" stroke="${light}" stroke-width="1"/><g filter="url(#arc-glass-shadow)"><path class="glass-arrow-head" d="M286 94Q284 90 288 90Q290 90 292 93L300 102L307 91Q310 87 313 90Q315 92 312 96L304 110Q301 115 297 111Z"/><path d="m288 93 12 13 10-14" class="glass-arrow-shine"/></g><g class="progress-vehicle glass-vehicle" style="transform:translate(${point.x}px,${point.y}px)"><circle r="15" class="progress-halo"/><circle r="11.5" fill="url(#arc-glass-bus)" stroke="white" stroke-width="2" filter="url(#arc-glass-shadow)"/><path d="M-7-5Q0-12 7-5" stroke="white" stroke-opacity=".65" stroke-width="1.7" fill="none" stroke-linecap="round"/><use href="#i-bus" x="-6" y="-5" width="12" height="12" stroke="white" fill="none" stroke-width="1.6"/></g></svg><span class="dome-time"><b>${a.remaining===null?'-':a.remaining}<small>${a.remaining===null?'':' min'}</small></b><span>${a.phase==='arrived'?'You’ve arrived':a.riding?'To your destination':a.phase==='at-stop'?'Bus at your stop':'Until your bus arrives'}</span></span><span class="arc-phase-label">${a.riding?'2 · Your ride':'1 · Bus to your stop'} <span>${Math.round(pct)}%</span></span></button>`};
let directionLoading=false,directionLoadStarted=0;
function syncDirectionLoading(){document.querySelectorAll('button[aria-label="Reverse journey direction"],.directiontabs button,button[onclick*="switchArrivalDirection"]').forEach(button=>{button.disabled=directionLoading;button.setAttribute('aria-busy',String(directionLoading));button.classList.toggle('direction-loading',directionLoading);button.style.setProperty('--loading-offset',-(performance.now()-directionLoadStarted)/1000+'s');if(directionLoading)button.setAttribute('title','Updating direction…');else button.removeAttribute('title')});let note=document.getElementById('direction-load-status');if(!note){note=document.createElement('span');note.id='direction-load-status';note.className='sr-only';note.setAttribute('role','status');document.body.append(note)}note.textContent=directionLoading?'Updating direction. Please wait.':''}
async function requestJourneyDirection(target){if(directionLoading||arrivalDirection===target)return;let route=arrivalRoute;directionLoading=true;directionLoadStarted=performance.now();syncDirectionLoading();try{await Promise.all([new Promise(resolve=>setTimeout(resolve,1100)),arrivalMode==='live'&&window.METRO_TELEMETRY_ENDPOINT?refreshLiveTelemetry():Promise.resolve()]);if(arrivalRoute!==route)return;arrivalDirection=target;networkReverse=target===-1;arrivalExpanded=false;arcTrip=null;arrivalBus='';rememberBoarding();render()}finally{directionLoading=false;syncDirectionLoading()}}
switchArrivalDirection=function(){return requestJourneyDirection(-arrivalDirection)};
const glassSelectedRoutePanel=selectedRoutePanel;selectedRoutePanel=function(){return glassSelectedRoutePanel().replace('onclick="networkReverse=false;render()"','onclick="requestJourneyDirection(1)"').replace('onclick="networkReverse=true;render()"','onclick="requestJourneyDirection(-1)"')};
const glassRender=render;render=function(){glassRender();syncDirectionLoading()};
render();

// Keep the SVG node and its animation timeline across the surrounding one-second refresh.
const stableArcRender=render;
render=function(){let existing=document.querySelector('.glass-dome'),animations=existing?.getAnimations?.({subtree:true}).filter(animation=>animation.animationName).map(animation=>({animation,time:animation.currentTime}))||[];stableArcRender();let fresh=document.querySelector('.glass-dome');if(!existing||!fresh||existing.dataset.arcKey!==fresh.dataset.arcKey)return;existing.setAttribute('aria-label',fresh.getAttribute('aria-label'));for(let selector of ['.dome-time','.arc-phase-label'])existing.querySelector(selector).innerHTML=fresh.querySelector(selector).innerHTML;for(let selector of ['.glass-fill-depth','.glass-fill-body','.glass-fill-shine']){let target=existing.querySelector(selector),value=fresh.querySelector(selector).getAttribute('stroke-dasharray');target.setAttribute('stroke-dasharray',value);target.style.strokeDasharray=value}existing.querySelector('.glass-vehicle').style.transform=fresh.querySelector('.glass-vehicle').style.transform;fresh.replaceWith(existing);for(let {animation,time} of animations){if(time!==null&&animation.playState!=='finished'){try{animation.currentTime=time;animation.play()}catch{}}}};
render();
